'use strict';
const {
  Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType,
  Table, TableRow, TableCell, BorderStyle, WidthType, ShadingType,
  PageBreak, LevelFormat, Footer, PageNumber
} = require('docx');
const fs = require('fs');

// ── ГОСТ 7.32 метрика (DXA, 1440 = 1 inch) ───────────────────────────────────
const ML = 1701;  // left 30 mm
const MR = 567;   // right 10 mm
const MT = 1134;  // top 20 mm
const MB = 1134;  // bottom 20 mm
const CW = 9638;  // content width = 11906 − ML − MR
const IND = 708;  // paragraph first-line indent 1.25 cm
const F  = 'Times New Roman';
const SZ = 28;    // 14 pt = 28 half-points
const SZ2 = 24;   // 12 pt for tables

function sp(before = 0, after = 0) {
  return { line: 360, lineRule: 'auto', before, after };
}

function p(text, o = {}) {
  const runs = Array.isArray(text) ? text : [{ t: text }];
  const children = runs.map((r, i) =>
    new TextRun({
      text: typeof r === 'string' ? r : r.t,
      font: F, size: o.size || SZ,
      bold: o.bold || (typeof r === 'object' && r.bold),
      italics: o.italic || (typeof r === 'object' && r.italic),
      break: i > 0 ? 1 : 0,
    })
  );
  return new Paragraph({
    alignment: o.center ? AlignmentType.CENTER : o.right ? AlignmentType.RIGHT : AlignmentType.BOTH,
    spacing: sp(o.before || 0, o.after || 0),
    indent: (o.noIndent || o.center || o.right) ? {} : { firstLine: IND },
    children,
  });
}

const empty = () => new Paragraph({ spacing: sp(), children: [new TextRun({ text: '', font: F, size: SZ })] });
const pb    = () => new Paragraph({ children: [new PageBreak()] });

function h1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    pageBreakBefore: true,
    alignment: AlignmentType.CENTER,
    spacing: sp(0, 300),
    children: [new TextRun({ text, font: F, size: SZ, bold: true })],
  });
}
function h2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    alignment: AlignmentType.BOTH,
    spacing: sp(280, 160),
    indent: { firstLine: IND },
    children: [new TextRun({ text, font: F, size: SZ, bold: true })],
  });
}
function caption(text) {
  return new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: sp(80, 60),
    children: [new TextRun({ text, font: F, size: SZ2, italics: true })],
  });
}
function li(text) {
  return new Paragraph({
    numbering: { reference: 'dashes', level: 0 },
    alignment: AlignmentType.BOTH,
    spacing: sp(0, 0),
    children: [new TextRun({ text, font: F, size: SZ })],
  });
}

function tbl(headers, rows, cols) {
  const brd = { style: BorderStyle.SINGLE, size: 4, color: '000000' };
  const borders = { top: brd, bottom: brd, left: brd, right: brd };
  const cell = (txt, hdr, w) => new TableCell({
    borders, width: { size: w, type: WidthType.DXA },
    margins: { top: 60, bottom: 60, left: 80, right: 80 },
    shading: hdr ? { fill: 'D9D9D9', type: ShadingType.CLEAR } : undefined,
    children: [new Paragraph({
      alignment: AlignmentType.CENTER,
      spacing: { line: 260, lineRule: 'auto' },
      children: [new TextRun({ text: String(txt), font: F, size: SZ2, bold: hdr })],
    })],
  });
  return new Table({
    width: { size: CW, type: WidthType.DXA },
    columnWidths: cols,
    rows: [
      new TableRow({ tableHeader: true, children: headers.map((h, i) => cell(h, true, cols[i])) }),
      ...rows.map(row => new TableRow({ children: row.map((c, i) => cell(c, false, cols[i])) })),
    ],
  });
}

